create type request_status as enum ('pending','accepted','declined','scheduled','completed','cancelled');
create table profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null,username text unique,bio text default '',city text,avatar_url text,teach text[] default '{}',learn text[] default '{}',availability jsonb default '{}',created_at timestamptz default now());
create table swap_requests(id uuid primary key default gen_random_uuid(),sender_id uuid references profiles(id),receiver_id uuid references profiles(id),goal text not null,status request_status default 'pending',scheduled_at timestamptz,created_at timestamptz default now(),check(sender_id<>receiver_id));
create table messages(id uuid primary key default gen_random_uuid(),request_id uuid references swap_requests(id) on delete cascade,sender_id uuid references profiles(id),body text not null,created_at timestamptz default now());
create table reviews(id uuid primary key default gen_random_uuid(),request_id uuid references swap_requests(id),reviewer_id uuid references profiles(id),reviewee_id uuid references profiles(id),rating int check(rating between 1 and 5),body text,unique(request_id,reviewer_id));
create table notifications(id uuid primary key default gen_random_uuid(),profile_id uuid references profiles(id),title text not null,body text,read_at timestamptz,created_at timestamptz default now());
alter table profiles enable row level security;alter table swap_requests enable row level security;alter table messages enable row level security;alter table reviews enable row level security;alter table notifications enable row level security;
create policy "public profiles" on profiles for select using(true);create policy "own profile" on profiles for update using(auth.uid()=id);create policy "request participants" on swap_requests for select using(auth.uid() in(sender_id,receiver_id));create policy "send requests" on swap_requests for insert with check(auth.uid()=sender_id);create policy "participant messages" on messages for select using(exists(select 1 from swap_requests r where r.id=request_id and auth.uid() in(r.sender_id,r.receiver_id)));create policy "own notifications" on notifications for select using(auth.uid()=profile_id);
